using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("ExpenseCategoriesController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/expense-categories")]
public sealed class ExpenseCategoriesController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet,RequirePermission("PurchaseExpense.ExpenseCategory",PermissionAction.View)]public async Task<IActionResult>List([FromQuery]ExpenseCategoryListQuery q,CancellationToken ct)=>FromResponse(await s.GetExpenseCategoriesAsync(q,ct));[HttpGet("{id:long}"),RequirePermission("PurchaseExpense.ExpenseCategory",PermissionAction.View)]public async Task<IActionResult>Get(long id,CancellationToken ct)=>FromResponse(await s.GetExpenseCategoryAsync(id,ct));[HttpPost,RequirePermission("PurchaseExpense.ExpenseCategory",PermissionAction.Create)]public async Task<IActionResult>Create(CreateExpenseCategoryRequest r,CancellationToken ct)=>FromResponse(await s.CreateExpenseCategoryAsync(r,ct),201);[HttpPut("{id:long}"),RequirePermission("PurchaseExpense.ExpenseCategory",PermissionAction.Edit)]public async Task<IActionResult>Update(long id,UpdateExpenseCategoryRequest r,CancellationToken ct)=>FromResponse(await s.UpdateExpenseCategoryAsync(id,r,ct));[HttpDelete("{id:long}"),RequirePermission("PurchaseExpense.ExpenseCategory",PermissionAction.Delete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>FromResponse(await s.DeleteExpenseCategoryAsync(id,ct)); }
